/** 실제 고객/KYC/CDD/세션/PG 위에 견적만 저장한다. 주소 노드 판독은 별도로 실제 Core 검증한 대역이다. */
class BitcoinWithdrawalQuoteIntegrationTest extends EddTestSupport {
    @DynamicPropertySource static void bitcoin(DynamicPropertyRegistry r){r.add("bitcoin.rpc-url",()->"http://127.0.0.1:1");r.add("bitcoin.rpc-user",()->"isolated");r.add("bitcoin.rpc-password",()->"isolated-withdrawal-quote-password-32-bytes");r.add("bitcoin.wallet",()->"watch");r.add("bitcoin.network",()->"REGTEST");}
    @Autowired BitcoinWithdrawalQuotes quotes;
    @MockitoBean BitcoinDestinationClient destination;
    static final String ADDRESS="bcrt1qquoteexample",SCRIPT="0014"+"ab".repeat(20);
    @BeforeEach void eligible()throws Exception{verify(false);clearInvocations(client);when(destination.validate(ADDRESS)).thenReturn(new BitcoinDestinationClient.Destination("bitcoin-regtest",ADDRESS,SCRIPT,"witness_v0_keyhash"));}
    // 공개 해시는 위변조 권한이 아니다. 저장소가 변조됐다는 대역에도 금액 재계산이 실패하는지 검증한다.
    static String sha256(String value){try{return java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(java.security.NoSuchAlgorithmException impossible){throw new IllegalStateException(impossible);}}
    long count(){return jdbc.queryForObject("SELECT count(*) FROM bitcoin_withdrawal_quotes",Long.class);}
    @AfterEach void neverMovesMoney(){verifyNoInteractions(engine,producer,client);assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM ledger_entries",Long.class));assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM user_balances",Long.class));}
    @Test void quoteRecordsTheExactFeeAndCanonicalRecipientWithoutReservingFunds(){
        var quote=quotes.prepare(customer.getId(),sid,UUID.randomUUID(),ADDRESS,"0.01");assertEquals("0.01000000",quote.payload().amount());assertEquals("0.00000100",quote.payload().fee());assertEquals("0.01000100",quote.payload().total());assertEquals("0.0001",quote.payload().feeRate());assertEquals(ADDRESS,quote.payload().address());assertEquals(SCRIPT,quote.payload().scriptPubKey());assertEquals("PRICED",quote.state());assertEquals(BitcoinWithdrawalQuotes.ASSURANCE,quote.assurance());assertEquals(1,count());
    }
    @Test void repeatedRequestKeepsTheSameQuoteAndDoesNotRepeatNodeWork(){UUID key=UUID.randomUUID();var first=quotes.prepare(customer.getId(),sid,key,ADDRESS,"0.01");var repeated=quotes.prepare(customer.getId(),sid,key,ADDRESS,"00.010000000");assertEquals(first,repeated);assertEquals(1,count());org.mockito.Mockito.verify(destination,times(1)).validate(ADDRESS);}
    @Test void mandatoryQuoteAuditFailureRollsBackTheQuote(){doThrow(new IllegalStateException("격리 출금 견적 감사 장애")).when(audit).record(eq(customer.getId()),eq("BTC_WITHDRAWAL_QUOTED"),anyString(),anyString(),anyString());assertThrows(IllegalStateException.class,()->quotes.prepare(customer.getId(),sid,UUID.randomUUID(),ADDRESS,"0.01"));assertEquals(0,count());}
    BitcoinWithdrawalQuotes.Quote price(){return quotes.prepare(customer.getId(),sid,UUID.randomUUID(),ADDRESS,"0.01");}
    org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder post(UUID key,String body){return org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/customer/withdrawals/BTC/quotes").header("Authorization","Bearer "+customerAccess).header("Idempotency-Key",key.toString()).contentType("application/json").content(body);}
    record Other(dustin.cex.domains.auth.model.entity.User user,UUID sid,String access){}
    Other other(){var user=users.saveAndFlush(dustin.cex.domains.auth.model.entity.User.builder().email(UUID.randomUUID()+"@test.invalid").passwordHash(hash).build());var token=tokens.saveAndFlush(dustin.cex.domains.auth.model.entity.RefreshToken.builder().userId(user.getId()).tokenHash(UUID.randomUUID().toString()).expiresAt(java.time.LocalDateTime.now().plusHours(1)).build());return new Other(user,token.getSessionId(),jwt.generateAccessToken(user.getId(),token.getSessionId()));}
    void shadow(BitcoinWithdrawalQuotes.Quote original,java.util.function.Consumer<tools.jackson.databind.node.ObjectNode> change){
        new org.springframework.transaction.support.TransactionTemplate(manager).executeWithoutResult(t->{
            var at=jdbc.queryForObject("SELECT clock_timestamp()",java.sql.Timestamp.class);var p=(tools.jackson.databind.node.ObjectNode)json.valueToTree(original.payload());UUID id=UUID.randomUUID();p.put("id",id.toString());p.put("createdAt",at.toInstant().toString());p.put("expiresAt",at.toInstant().plusSeconds(120).toString());change.accept(p);
            String raw=json.writeValueAsString(p),digest=sha256(raw);
            long owner=Long.parseLong(p.path("customerId").stringValue());
            jdbc.update("INSERT INTO bitcoin_withdrawal_quotes(id,user_id,user_version,session_id,request_key,input_hash,network,amount,fee,total,policy,payload,payload_hash,created_at,expires_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",id,owner,p.path("customerVersion").longValue(),sid,UUID.randomUUID(),"f".repeat(64),p.path("network").stringValue(),new java.math.BigDecimal(p.path("amount").asString()),new java.math.BigDecimal(p.path("fee").asString()),new java.math.BigDecimal(p.path("total").asString()),original.payload().policy(),raw,digest,at,java.sql.Timestamp.from(at.toInstant().plusSeconds(120)));
            audit.record(owner,"BTC_WITHDRAWAL_QUOTED","bitcoin-withdrawal-quote:"+id,"SUCCESS",digest);
        });
    }
    @Test void silentlyOmittedQuoteAuditCannotCommit(){doNothing().when(audit).record(eq(customer.getId()),eq("BTC_WITHDRAWAL_QUOTED"),anyString(),anyString(),anyString());assertThrows(org.springframework.dao.DataAccessException.class,this::price);assertEquals(0,count());}
    @Test void invalidKeyAmountAddressAndAmbientTransactionDoNotCallTheNode(){
        for(UUID key:List.of(new UUID(0,0)))assertEquals(400,assertThrows(org.springframework.web.server.ResponseStatusException.class,()->quotes.prepare(customer.getId(),sid,key,ADDRESS,"0.01")).getStatusCode().value());
        assertEquals(400,assertThrows(org.springframework.web.server.ResponseStatusException.class,()->quotes.prepare(customer.getId(),sid,null,ADDRESS,"0.01")).getStatusCode().value());
        for(String value:List.of("0","-1","1E-8","0.000000001","21000000"))assertEquals(400,assertThrows(org.springframework.web.server.ResponseStatusException.class,()->quotes.prepare(customer.getId(),sid,UUID.randomUUID(),ADDRESS,value)).getStatusCode().value());
        assertEquals(400,assertThrows(org.springframework.web.server.ResponseStatusException.class,()->quotes.prepare(customer.getId(),sid,UUID.randomUUID()," ","0.01")).getStatusCode().value());
        assertThrows(IllegalStateException.class,()->new org.springframework.transaction.support.TransactionTemplate(manager).execute(t->price()));assertEquals(0,count());verifyNoInteractions(destination);
    }
    @Test void theSameKeyCannotSwitchAmountOrDestination(){UUID key=UUID.randomUUID();var original=quotes.prepare(customer.getId(),sid,key,ADDRESS,"0.01");for(boolean changedAmount:List.of(true,false)){assertEquals(409,assertThrows(org.springframework.web.server.ResponseStatusException.class,()->quotes.prepare(customer.getId(),sid,key,changedAmount?ADDRESS:"bcrt1qchanged",changedAmount?"0.02":"0.01")).getStatusCode().value());}assertEquals(original,quotes.own(customer.getId(),sid,original.payload().id()));assertEquals(1,count());org.mockito.Mockito.verify(destination).validate(ADDRESS);}
    @Test void theSameKeyCannotMoveToAnotherSession(){UUID key=UUID.randomUUID();quotes.prepare(customer.getId(),sid,key,ADDRESS,"0.01");var token=tokens.saveAndFlush(dustin.cex.domains.auth.model.entity.RefreshToken.builder().userId(customer.getId()).tokenHash(UUID.randomUUID().toString()).expiresAt(java.time.LocalDateTime.now().plusHours(1)).build());assertEquals(409,assertThrows(org.springframework.web.server.ResponseStatusException.class,()->quotes.prepare(customer.getId(),token.getSessionId(),key,ADDRESS,"0.01")).getStatusCode().value());assertEquals(1,count());org.mockito.Mockito.verify(destination).validate(ADDRESS);}
    @Test void anotherCustomersAndMissingQuotesAreBothNotFound()throws Exception{
        var quote=price();var other=other();for(UUID id:List.of(quote.payload().id(),UUID.randomUUID())){assertEquals(404,assertThrows(org.springframework.web.server.ResponseStatusException.class,()->quotes.own(other.user().getId(),other.sid(),id)).getStatusCode().value());mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get("/api/customer/withdrawals/BTC/quotes/"+id).header("Authorization","Bearer "+other.access()).param("userId",customer.getId().toString())).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isNotFound());}}
    @Test void operatorForeignRevokedAndMissingSessionsCannotPrepare(){
        assertEquals(403,assertThrows(org.springframework.web.server.ResponseStatusException.class,()->quotes.prepare(maker.user().getId(),maker.sid(),UUID.randomUUID(),ADDRESS,"0.01")).getStatusCode().value());
        for(UUID supplied:List.of(maker.sid(),UUID.randomUUID()))assertEquals(403,assertThrows(org.springframework.web.server.ResponseStatusException.class,()->quotes.prepare(customer.getId(),supplied,UUID.randomUUID(),ADDRESS,"0.01")).getStatusCode().value());
        assertEquals(403,assertThrows(org.springframework.web.server.ResponseStatusException.class,()->quotes.prepare(customer.getId(),null,UUID.randomUUID(),ADDRESS,"0.01")).getStatusCode().value());
        var token=tokens.findBySessionId(sid).orElseThrow();token.setRevoked(true);tokens.saveAndFlush(token);assertEquals(403,assertThrows(org.springframework.web.server.ResponseStatusException.class,this::price).getStatusCode().value());assertEquals(0,count());verifyNoInteractions(destination);
    }
    @Test void unverifiedCustomerCannotReceiveANewQuote(){var other=other();assertEquals(403,assertThrows(org.springframework.web.server.ResponseStatusException.class,()->quotes.prepare(other.user().getId(),other.sid(),UUID.randomUUID(),ADDRESS,"0.01")).getStatusCode().value());verifyNoInteractions(destination);assertEquals(0,count());}
    @Test void tradingRestrictionBlocksNewQuotesWithoutHidingThePast(){UUID key=UUID.randomUUID();var old=quotes.prepare(customer.getId(),sid,key,ADDRESS,"0.01");var owner=users.findById(customer.getId()).orElseThrow();owner.setTradingRestricted(true);users.saveAndFlush(owner);assertEquals(old,quotes.own(customer.getId(),sid,old.payload().id()));assertEquals(old,quotes.prepare(customer.getId(),sid,key,ADDRESS,"0.01"));assertEquals(403,assertThrows(org.springframework.web.server.ResponseStatusException.class,this::price).getStatusCode().value());org.mockito.Mockito.verify(destination).validate(ADDRESS);}
    @Test void currentAccountDisableAlsoStopsHistoricalAccess(){var quote=price();var owner=users.findById(customer.getId()).orElseThrow();owner.setEnabled(false);users.saveAndFlush(owner);assertEquals(403,assertThrows(org.springframework.web.server.ResponseStatusException.class,()->quotes.own(customer.getId(),sid,quote.payload().id())).getStatusCode().value());assertEquals(1,count());}
    @Test void nodeIoDoesNotHoldTheCustomerRowOrDatabaseTransaction(){
        when(destination.validate(ADDRESS)).thenAnswer(call->{assertFalse(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive());try(var connection=jdbc.getDataSource().getConnection()){connection.setAutoCommit(false);try(var statement=connection.createStatement()){assertTrue(statement.executeQuery("SELECT id FROM users WHERE id="+customer.getId()+" FOR UPDATE NOWAIT").next());}connection.rollback();}return new BitcoinDestinationClient.Destination("bitcoin-regtest",ADDRESS,SCRIPT,"witness_v0_keyhash");});assertEquals("PRICED",price().state());
    }
    @Test void customerVersionChangeDuringNodeReadPreventsTheNewQuote(){
        when(destination.validate(ADDRESS)).thenAnswer(call->{var owner=users.findById(customer.getId()).orElseThrow();owner.setEmail(UUID.randomUUID()+"@test.invalid");users.saveAndFlush(owner);return new BitcoinDestinationClient.Destination("bitcoin-regtest",ADDRESS,SCRIPT,"witness_v0_keyhash");});assertEquals(409,assertThrows(org.springframework.web.server.ResponseStatusException.class,this::price).getStatusCode().value());assertEquals(0,count());
    }
    @Test void currentTradingRestrictionDuringNodeReadCannotUseTheEarlierPermission(){when(destination.validate(ADDRESS)).thenAnswer(call->{var owner=users.findById(customer.getId()).orElseThrow();owner.setTradingRestricted(true);users.saveAndFlush(owner);return new BitcoinDestinationClient.Destination("bitcoin-regtest",ADDRESS,SCRIPT,"witness_v0_keyhash");});assertEquals(409,assertThrows(org.springframework.web.server.ResponseStatusException.class,this::price).getStatusCode().value());assertEquals(0,count());}
    @Test void sourceFailureIsNotAUserAuthenticationDenial(){when(destination.validate(ADDRESS)).thenThrow(new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.SERVICE_UNAVAILABLE,"격리 노드 확인 실패"));assertEquals(503,assertThrows(org.springframework.web.server.ResponseStatusException.class,this::price).getStatusCode().value());assertEquals(0,count());assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM security_audit WHERE action='BTC_WITHDRAWAL_QUOTE_FAILED' AND outcome='FAILURE'",Long.class));assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM security_audit WHERE action='BTC_WITHDRAWAL_QUOTE_REQUEST' AND outcome='DENIED'",Long.class));}
    @Test void replayAndReadAuditFailuresDoNotHideTheCommittedOriginal(){UUID key=UUID.randomUUID();var quote=quotes.prepare(customer.getId(),sid,key,ADDRESS,"0.01");doThrow(new IllegalStateException("격리 견적 재조회 감사 실패")).when(audit).record(eq(customer.getId()),eq("BTC_WITHDRAWAL_QUOTE_REPLAYED"),anyString(),anyString(),anyString());assertThrows(IllegalStateException.class,()->quotes.prepare(customer.getId(),sid,key,ADDRESS,"0.01"));doThrow(new IllegalStateException("격리 견적 조회 감사 실패")).when(audit).record(eq(customer.getId()),eq("BTC_WITHDRAWAL_QUOTE_READ"),anyString(),anyString(),anyString());assertThrows(IllegalStateException.class,()->quotes.own(customer.getId(),sid,quote.payload().id()));assertEquals(1,count());org.mockito.Mockito.verify(destination).validate(ADDRESS);}
    @Test void quoteCannotBeEditedDeletedOrTruncated(){price();for(String sql:List.of("UPDATE bitcoin_withdrawal_quotes SET amount=amount","DELETE FROM bitcoin_withdrawal_quotes","TRUNCATE bitcoin_withdrawal_quotes CASCADE"))assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.execute(sql));assertEquals(1,count());}
    @Test void aNewPublicHashCannotAuthorizeAWrongFeeOrTotal(){var original=price();var failure=assertThrows(org.springframework.dao.DataAccessException.class,()->shadow(original,p->{p.put("fee","0.00001000");p.put("total","0.01001000");}));assertTrue(org.springframework.core.NestedExceptionUtils.getMostSpecificCause(failure).getMessage().contains("check constraint"));assertEquals(1,count());}
    @Test void extraMissingAndCoercedQuoteFieldsCannotEnterTheRecord(){var original=price();for(int variant:List.of(0,1,2)){assertThrows(org.springframework.dao.DataAccessException.class,()->shadow(original,p->{if(variant==0)p.put("extra",true);else if(variant==1)p.remove("policy");else p.put("fee",new java.math.BigDecimal("0.00000100"));}));}assertEquals(1,count());}
    @Test void anotherRoleOrNetworkCannotForgeACustomerQuote(){var original=price();assertThrows(org.springframework.dao.DataAccessException.class,()->shadow(original,p->{p.put("customerId",maker.user().getId().toString());p.put("customerVersion",users.findById(maker.user().getId()).orElseThrow().getVersion());}));assertThrows(org.springframework.dao.DataAccessException.class,()->shadow(original,p->p.put("network","bitcoin-mainnet")));assertEquals(1,count());}
    @Test void sourceNetworkCannotSilentlyMixWithTheBoundDatabase(){when(destination.validate(ADDRESS)).thenReturn(new BitcoinDestinationClient.Destination("bitcoin-mainnet",ADDRESS,SCRIPT,"witness_v0_keyhash"));assertThrows(org.springframework.dao.DataAccessException.class,this::price);assertEquals(0,count());}
    @Test void quoteReadRejectsAlteredMoneyEvenWithARecomputedPublicHash(){
        var original=price();var database=spy(jdbc);doAnswer(call->{var rows=jdbc.queryForList(call.getArgument(0,String.class),new Object[]{call.getArgument(1),call.getArgument(2)});for(var row:rows){var p=(tools.jackson.databind.node.ObjectNode)json.readTree((String)row.get("payload"));p.put("fee","0.00001000");String raw=json.writeValueAsString(p);row.put("payload",raw);row.put("payload_hash",sha256(raw));}return rows;}).when(database).queryForList(startsWith("SELECT *,expires_at>clock_timestamp() fresh"),eq(customer.getId()),any(UUID.class));
        var changed=new BitcoinWithdrawalQuotes(database,sessionsForQuotes(),eligibilityForQuotes(),destination,audit,json,manager);assertThrows(IllegalStateException.class,()->changed.own(customer.getId(),sid,original.payload().id()));assertEquals(original,quotes.own(customer.getId(),sid,original.payload().id()));
    }
    @Autowired dustin.cex.domains.security.CustomerSessionPolicy quoteSessions;
    @Autowired dustin.cex.domains.security.CustomerFinancialEligibility quoteEligibility;
    dustin.cex.domains.security.CustomerSessionPolicy sessionsForQuotes(){return quoteSessions;}
    dustin.cex.domains.security.CustomerFinancialEligibility eligibilityForQuotes(){return quoteEligibility;}
    @Test void concurrentSameRequestsKeepOneQuoteAndOneCreationAudit()throws Exception{
        UUID key=UUID.randomUUID();var ready=new java.util.concurrent.CountDownLatch(2);var release=new java.util.concurrent.CountDownLatch(1);when(destination.validate(ADDRESS)).thenAnswer(call->{ready.countDown();assertTrue(release.await(5,java.util.concurrent.TimeUnit.SECONDS));return new BitcoinDestinationClient.Destination("bitcoin-regtest",ADDRESS,SCRIPT,"witness_v0_keyhash");});
        try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var a=pool.submit(()->quotes.prepare(customer.getId(),sid,key,ADDRESS,"0.01"));var b=pool.submit(()->quotes.prepare(customer.getId(),sid,key,ADDRESS,"0.01"));assertTrue(ready.await(5,java.util.concurrent.TimeUnit.SECONDS));release.countDown();assertEquals(a.get(10,java.util.concurrent.TimeUnit.SECONDS),b.get(10,java.util.concurrent.TimeUnit.SECONDS));}finally{release.countDown();}assertEquals(1,count());assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM security_audit WHERE action='BTC_WITHDRAWAL_QUOTED'",Long.class));
    }
    @Test void customerHttpReturnsOnlyAServerPricedQuote()throws Exception{String body=mvc.perform(post(UUID.randomUUID(),"{\"address\":\""+ADDRESS+"\",\"amount\":\"0.01\"}").param("userId",maker.user().getId().toString())).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isOk()).andReturn().getResponse().getContentAsString();var quote=json.readTree(body);assertEquals(customer.getId().toString(),quote.path("payload").path("customerId").stringValue());assertEquals("0.00000100",quote.path("payload").path("fee").stringValue());assertEquals("0.01000100",quote.path("payload").path("total").stringValue());assertEquals(BitcoinWithdrawalQuotes.ASSURANCE,quote.path("assurance").stringValue());assertFalse(body.contains(sid.toString()));}
    @Test void customerHttpRejectsNumericAmountsAndInjectedFeesUnknownFieldsOrDuplicateBodies()throws Exception{
        for(String raw:List.of("{}","{","{\"address\":\""+ADDRESS+"\",\"amount\":0.01}","{\"address\":\""+ADDRESS+"\",\"amount\":\"0.01\",\"fee\":\"0\"}","{\"address\":\""+ADDRESS+"\",\"amount\":\"0.01\",\"amount\":\"0.02\"}","{\"address\":\""+ADDRESS+"\",\"amount\":\"0.01\"}{}"))mvc.perform(post(UUID.randomUUID(),raw)).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isBadRequest());verifyNoInteractions(destination);assertEquals(0,count());assertEquals(6,jdbc.queryForObject("SELECT count(*) FROM security_audit WHERE action='BTC_WITHDRAWAL_QUOTE_REQUEST' AND detail='INVALID_BODY'",Long.class));
    }
    @Test void customerHttpRejectsOversizedBodiesAndDoesNotCallTheNode()throws Exception{mvc.perform(post(UUID.randomUUID(),"{\"address\":\""+"A".repeat(2100)+"\",\"amount\":\"0.01\"}")).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isPayloadTooLarge());assertEquals(0,count());verifyNoInteractions(destination);}
    @Test void anonymousAndOperatorCannotReachTheQuoteController()throws Exception{String raw="{\"address\":\""+ADDRESS+"\",\"amount\":\"0.01\"}";mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/customer/withdrawals/BTC/quotes").header("Authorization","Bearer "+maker.access()).header("Idempotency-Key",UUID.randomUUID().toString()).contentType("application/json").content(raw)).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isForbidden());mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/customer/withdrawals/BTC/quotes").header("Idempotency-Key",UUID.randomUUID().toString()).contentType("application/json").content(raw)).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isUnauthorized());assertEquals(0,count());verifyNoInteractions(destination);}
    @Test void anExpiredQuoteIsHistoricalAndCannotBeSilentlyRenewed(){UUID key=UUID.randomUUID();var original=quotes.prepare(customer.getId(),sid,key,ADDRESS,"0.01");org.awaitility.Awaitility.await().atMost(java.time.Duration.ofSeconds(130)).pollInterval(java.time.Duration.ofSeconds(2)).untilAsserted(()->assertEquals("EXPIRED",quotes.own(customer.getId(),sid,original.payload().id()).state()));var replay=quotes.prepare(customer.getId(),sid,key,ADDRESS,"0.01");assertEquals("EXPIRED",replay.state());assertEquals(original.payload(),replay.payload());assertEquals(original.payloadHash(),replay.payloadHash());assertEquals(1,count());org.mockito.Mockito.verify(destination).validate(ADDRESS);}

}
